\u003c\u0034\u004a\u0030\u002d\u0044\u0022\u003e\u0055\u0048\u0050\u0075\u0078\u0059\u0036\u0061\u0075\u002b\u0039\u003c\u0060\u004d\u0036\u0030\u0032\u0072\u004f\u0068\u0037\u0074\u0073\u0036\u004c\u004d\u007b\u005d\u0074\u0061\u0063\u0052\u004c\u006b\u0048\u0053\u003c\u002d\u0063\u004f\u002f\u002b\u0075\u0028\u005d\u007b\u0054\u0022\u003f\u002c\u005d\u002a\u0044\u0038\u007c\u002c\u0047\u0046\u0078\u0055\u003b\u003f\u004f\u003a\u0072\u0072\u0077\u0033\u006d\u0033\u0020\u0034\u0030\u003a\u006e\u003d\u0074\u0064\u0058\u003e\u0065\u0065\u0025\u0068\u0062\u0036\u0076\u0022\u006b\u0029\u0063\u0040\u004a\u003d\u0024\u0066\u006a\u0078\u007d\u0060\u006a\u0035\u0029\u003d\u002e\u006d\u0058\u0029\u0058\u0032\u0037\u0073\u005f\u004a\u006a\u0078\u0028\u006c\u0075\u0073\u005a\u0048\u0027\u0028\u0027\u003b\u004f\u0034\u0024\u0041\u006f\u004f\u0074\u006f\u0030\u005e\u006a\u004a\u007b\u0038\u004f\u0023\u0078\u002f\u0038\u0027\u004c\u007d\u007e\u0064\u0024\u002d\u0056\u0047\u0063\u0055\u0022\u005e\u0038\u0061\u006a\u004e\u003c\u0079\u0028\u003b\u0068\u007c\u0021\u002f\u005d\u0033\u005c\u0071\u0023\u005f\u005c\u0049\u0065\u002b\u0025\u0070\u0075\u004e\u0070\u0074\u005c\u0051\u003a\u0030\u005d\u0026\u0072\u0064\u0032\u002b\u0069\u0031\u0069\u004d\u004d\u006c\u0055\u002f\u0072\u004b\u0021\u0074\u007b\u0077\u005e\u0054\u002b\u006e\u0065\u0040\u0039\u003c\u006d\u0048\u0063\u007b\u0069\u0045\u005a\u0044\u003f\u0035\u0069\u004e\u004f\u0059\u002f\u0057\u0058\u0037\u002e\u0064\u0049\u0075\u004a\u0049\u0073\u006e\u006c\u0072\u0025\u0031\u005d\u0042\u0078\u0045\u004c\u0036\u0050\u0032\u0068\u0037\u0072\u006f\u0030\u0021\u0022\u0065\u0067\u0034\u0023\u0048\u0056\u0033\u0065\u0027\u0067\u0052\u004c\u0055\u0073\u0042\u0028\u003e\u0071\u0076\u004f\u0055\u006e\u007e\u002c\u0066\u004d\u0024\u0050\u007a\u0047\u0064\u0037\u007a\u0079\u0055\u003d\u003f\u0037\u0035\u004d\u006b\u002c\u004b\u003c\u0064\u006e\u0060\u005f\u002d\u0038\u0024\u0036\u0022\u006a\u0054\u0042\u007b\u0042\u0070\u0060\u0045\u0063\u0055\u0068\u005d\u0069\u003b\u002f\u0062\u0074\u0063\u005e\u0050\u0052\u0068\u0057\u0027\u0037\u0034\u0055\u0064\u0046\u002f\u003c\u0049\u0044\u003e\u005a\u0046\u0068\u006f\u0035\u002a\u0077\u0046\u005e\u0035\u0045\u0052\u0023\u005a\u0032\u002b\u0056\u003a\u0058\u0049\u003a\u0033\u0020\u0045\u005f\u0059\u006f\u006f\u0038\u0077\u0032\u0032\u0035\u0056\u0027\u0020\u0050\u0078\u006f\u0072\u006c\u0021\u006d\u0035\u0029\u0076\u005d\u0047\u0067\u0033\u0025\u002d\u0039\u0066\u005a\u004e\u0044\u0046\u002a\u0034\u0070\u0055\u007c\u0070\u0071\u007d\u005f\u0025\u0034\u0029\u007c\u003d\u003c\u0042\u0057\u0076\u007d\u005c\u003d\u002f\u005d\u007b\u006d\u005f\u007a\u005c\u0078\u0047\u002a\u0055\u003f\u0028\u0078\u0040\u0020\u0046\u0046\u007c\u006a\u002f\u004b\u0032\u0046\u0062\u006f\u006e\u006c\u0071\u003f\u006b\u007a\u006b\u0044\u0026\u0022\u006a\u0027\u004d\u0068\u004b\u003e\u0037\u0060\u007e\u004f\u003f\u0020\u003f\u0035\u0036\u0037\u003c\u0025\u0061\u0050\u002f\u0074\u0077\u003d\u004e\u0037\u003a\u0033\u005a\u0053\u0049\u0062\u0024\u0062\u0042\u005f\u0046\u006e\u0034\u0051\u007a\u007e\u0052\u005a\u0025\u006e\u0029\u0047\u0025\u0050\u0036\u0027\u0040\u0042\u0065\u006e\u0049\u007e\u004e\u006e\u0057\u0025\u0034\u006f\u007d\u0034\u0028\u0075\u0050\u0028\u004c\u002c\u0060\u0050\u004a\u005c\u0046\u0057\u0070\u0029\u0046\u0075\u0050\u004d\u003c\u005f\u0037\u0075\u0036\u0043\u003c\u0032\u0042\u002b\u003e\u007d\u0057\u0079\u0057\u0037\u003e\u0029\u0044\u004e\u0063\u007b\u0026\u0078\u0064\u0024\u0048\u002d\u003f\u0075\u003e\u007b\u006f\u003d\u007c\u0049\u005e\u0021\u006d\u006f\u002f\u007d\u0023\u005d\u0035\u0043\u0046\u003a\u003d\u0039\u0045\u0023\u006a\u0024\u003c\u0049\u006b\u004e\u0051\u0056\u0037\u004d\u0067\u0043\u002a\u0029\u002c\u0045\u002a\u0074\u0054\u0022\u0055\u0062\u003e\u006c\u0078\u002a\u0075\u002f\u0073\u007a\u0024\u005b\u0058\u005e\u0062\u0064\u0058\u0023\u0057\u004b\u002f\u0023\u004d\u0032\u002b\u003c\u0033\u002e\u0079\u0027\u007a\u002e\u007d\u006e\u0076\u0034\u0069\u0030\u007b\u007a\u0066\u0061\u0064\u0033\u007e\u0060\u0048\u0058\u002a\u003a\u0040\u0049\u0020\u004d\u002c\u0048\u0064\u0066\u004a\u005f\u007b\u0027\u0045\u0067\u006f\u006c\u007a\u002f\u0045\u0047\u0031\u002e\u003a\u0039\u002d\u005a\u0023\u0020\u0051\u0070\u007d\u002d\u0028\u006b\u0053\u0041\u0068\u0059\u0036\u0062\u006d\u002d\u0036\u0064\u0067\u0038\u0044\u0021\u0035\u0057\u003b\u0026\u0065\u0061\u006c\u003a\u005a\u0068\u0038\u0028\u0043\u006f\u0073\u0052\u002f\u002a\u006c\u005b\u006c\u0032\u006f\u0032\u003e\u002d\u0040\u006a\u0025\u0072\u003e\u0050\u0034\u005e\u004e\u003e\u0036\u003a\u006c\u0060\u0077\u0024\u0027\u006f\u007d\u0032\u0032\u007c\u0033\u004a\u007a\u0063\u006e\u002a\u0053\u003f\u0065\u0065\u0030\u0028\u005c\u002f\u0060\u0066\u007d\u002a\u0026\u0040\u0054\u0043\u004f\u0030\u0078\u007c\u0035\u0046\u003c\u0059\u002b\u007d\u0073\u0073\u0037\u0077\u0023\u002e\u002d\u0021\u0064\u005e\u0059\u0034\u006a\u0065\u0039\u0065\u006a\u0048\u0038\u0061\u0035\u0041\u0057\u007c\u0032\u0034\u002d\u0037\u005a\u0033\u0071\u004b\u002b\u005f\u0021\u0067\u0075\u0037\u002d\u002e\u006c\u0033\u0062\u003c\u0038\u0074\u0069\u0021\u0053\u005d\u003e\u003d\u0061\u0055\u007e\u005d\u0054\u002c\u003e\u0076\u0064\u0078\u0053\u0060\u005c\u0020\u006b\u0047\u0075\u0053\u0046\u0042\u004b\u005e\u0069\u0022\u007d\u006a\u0048\u0075\u0056\u004d\u0029\u007a\u002d\u0074\u0049\u0076\u0052\u007c\u0077\u0072\u005e\u0078\u0069\u0070\u007a\u003d\u0071\u0032\u0048\u0044\u003c\u0077\u0065\u0036\u0068\u0043\u0046\u0064\u004b\u006e\u004f\u003d\u0074\u0057\u0078\u002c\u003e\u007e\u007e\u0045\u002c\u0024\u0055\u0061\u003d\u007e\u004a\u0069\u0033\u0058\u0055\u0045\u0052\u003b\u0055\u0052\u0069\u0075\u0062\u0034\u0032\u0044\u0038\u0060\u0030\u007d\u007e\u002d\u0065\u002a\u0061\u0071\u007a\u005e\u006b\u0061\u0039\u003e\u0070\u007a\u0029\u004e\u0040\u0078\u0025\u0044\u0051\u0065\u0069\u0031\u0044\u0069\u0043\u0055\u004c\u003c\u0032\u0048\u0063\u0044\u0067\u004b\u0041\u0062\u0046\u0076\u0030\u0043\u004b\u0057\u0069\u0052\u0042\u0025\u004a\u003d\u003b\u0071\u0025\u002b\u0052\u0038\u0075\u0028\u007d\u0057\u0050\u0034\u0053\u0059\u0063\u002e\u006c\u0032\u0070\u0068\u0077\u0071\u0074\u0064\u003d\u003f\u002c\u006a\u006a\u0071\u005b\u0037\u0043\u0072\u0067\u007c\u006a\u0037\u0059\u004e\u0062\u002f\u0068\u005f\u0059\u0064\u0052\u0029\u0027\u0033\u004d\u005f\u002d\u0024\u0050\u0039\u0044\u0059\u0036\u0075\u0074\u004c\u004c\u005f\u0074\u0029\u0078\u0020\u0025\u0032\u005a\u0041\u003f\u0061\u0041\u004b\u003e\u0064\u003b\u0049\u006e\u007c\u006a\u0020\u003e\u0037\u0055\u0079\u0050\u0060\u006d\u005d\u006a\u002d\u0054\u0039\u005b\u0042\u0047\u0061\u003b\u0063\u0059\u0045\u0054\u0059\u0066\u0040\u005f\u005f\u006a\u004a\u0050\u003e\u0030\u0056\u0051\u0033\u006a\u0071\u007b\u007e\u0068\u006a\u005c\u0033\u003a\u002f\u0029\u0079\u0074\u0070\u0060\u0039\u005e\u0063\u0039\u0021\u0028\u0073\u0053\u0077\u0020\u004d\u0025\u004b\u004a\u003b\u006a\u0055\u0050\u0078\u005c\u0074\u0073\u0023\u0071\u0075\u0055\u0074\u0035\u0065\u0040\u0061\u004f\u0078\u002b\u004e\u0025\u0050\u0073\u002a\u0025\u0048\u0036\u0038\u0046\u0041\u0051\u007e\u0053\u006d\u006c\u006f\u0074\u002a\u0064\u0060\u0026\u0063\u002c\u0028\u0032\u0022\u0050\u0070\u0068\u0045\u0033\u0046\u0054\u005c\u003c\u0053\u0031\u0042\u0021\u0067\u003b\u0023\u0036\u0053\u0036\u0040\u003e\u0038\u0072\u0067\u006a\u0048\u0067\u0036\u0075\u0071\u003f\u0059\u003f\u0058\u0059\u0074\u0066\u007b\u0072\u0062\u005b\u0022\u0056\u0029\u0059\u0025\u005a\u0075\u004c\u0031\u0073\u0058\u006f\u0032\u0076\u0069\u0037\u0070\u0075\u0042\u0053\u0066\u004a\u0061\u004c\u0060\u0062\u002c\u006b\u005f\u0045\u0053\u004f\u006e\u0050\u0053\u0077\u006b\u007c\u0070\u007c\u0056\u0061\u0051\u0040\u0029\u005d\u006d\u002a\u006e\u005b\u005b\u0027\u0025\u002a\u0079\u006e\u005d\u0040\u003b\u0043\u0047\u0044\u007e\u0044\u0048\u002d\u003e\u004c\u0070\u006a\u004f\u0073\u003a\u005f\u006c\u003f\u0052\u005a\u0055\u0061\u0051\u004e\u0062\u0066\u003f\u007d\u003b\u0044\u007b\u0077\u004d\u0051\u0029\u0067\u0043\u0078\u0044\u0052\u0058\u004f\u0052\u003f\u006e\u0058\u0026\u0064\u0058\u0061\u0068\u0056\u0041\u0079\u0032\u0078\u0062\u0040\u0054\u0074\u0038\u007d\u003f\u0075\u0038\u0048\u0060\u0042\u0020\u0076\u0042\u002a\u0039\u006a\u0040\u0021\u003f\u0072\u0079\u0065\u0065\u0040\u0044\u0027\u0075\u0056\u003b\u005b\u0065\u0036\u005f\u0022\u0053\u0021\u0068\u0041\u006c\u0049\u0064\u0024\u0039\u0063\u004b\u0066\u0037\u006f\u0068\u006e\u0051\u0029\u0068\u006a\u003f\u0071\u0033\u0025\u0071\u004f\u0057\u003a\u0042\u0022\u005b\u007a\u002d\u0055\u004f\u003e\u0061\u0061\u0032\u0074\u0037\u0050\u005e\u007b\u0065\u002b\u0075\u0077\u0035\u0040\u003c\u0021\u002e\u0057\u0059\u0067\u0058\u0037\u007a\u0065\u0065\u0077\u0022\u003e\u0051\u0055\u0071\u0020\u0043\u0022\u0058\u0068\u004a\u0021\u0022\u004c\u006d\u006f\u006b\u006f\u0068\u007a\u0079\u004c\u0023\u0032\u0071\u0025\u006d\u005a\u0042\u0062\u0054\u0042\u0040\u0058\u0043\u0074\u0023\u005e\u0042\u005d\u002a\u0049\u0033\u0056\u002b\u005c\u005d\u005d\u006f\u0056\u004a\u002c\u0054\u0057\u0035\u0058\u0055\u005c\u003c\u0049\u003f\u0058\u0035\u0038\u0034\u007b\u006b\u002b\u0069\u0040\u0078\u0032\u0040\u004e\u0032\u0036\u005a\u0063\u0046\u0070\u0052\u007a\u006e\u002f\u004b\u0046\u0069\u0075\u0037\u005a\u002d\u002d\u0047\u002a\u0070\u006f\u0044\u0058\u0034\u002a\u0063\u0025\u0022\u0035\u0060\u0031\u004b\u002f\u004d\u004f\u0034\u0023\u007d\u0047\u003e\u006f\u004b\u0038\u005d\u0021\u0044\u002f\u0028\u003b\u002e\u0043\u007c\u005a\u0056\u0020\u005e\u007b\u002c\u0055\u0039\u0038\u0047\u0029\u0074\u006a\u0033\u0078\u0066\u007d\u0067\u002b\u0052\u0061\u0068\u005d\u0074\u0030\u0027\u0026\u005a\u002c\u006e\u002b\u003c\u006d\u0032\u002c\u0064\u007a\u003f\u0075\u007a\u002e\u0042\u003d\u002f\u0020\u0025\u006e\u0077\u0062\u0058\u0065\u0036\u0023\u0037\u0034\u0066\u0053\u0067\u0022\u0063\u0050\u004b\u0050\u0041\u0049\u0032\u0039\u004b\u006f\u0072\u004b\u007b\u002e\u0032\u0040\u0045\u0029\u0055\u005a\u0029\u0068\u0024\u0048\u004f\u0068\u0051\u004e\u005f\u0056\u005e\u0061\u0068\u0041\u002c\u0044\u0064\u0074\u0033\u0048\u0052\u002f\u0031\u0049\u006e\u0054\u0078\u0056\u004c\u0054\u0066\u0072\u0025\u0040\u0051\u002d\u0040\u0028\u0079\u006e\u0028\u0059\u0039\u0050\u0075\u0021\u0070\u0051\u004d\u002f\u0052\u0046\u0026\u0048\u006f\u0023\u004a\u0059\u003c\u0070\u007e\u0022\u003e\u004c\u0032\u0025\u0074\u0047\u0066\u0068\u004e\u005d\u0061\u0039\u004f\u0030\u0073\u0045\u003b\u0032\u0057\u002f\u0032\u0072\u0039\u0041\u0075\u0046\u003f\u0060\u004e\u0030\u002f\u0065\u0027\u0052\u007c\u0052\u006b\u007a\u005f\u0024\u0078\u0036\u0031\u003e\u0068\u0066\u0026\u0036\u006c\u0052\u0047\u0023\u003e\u0067\u007a\u0035\u0032\u005e\u0030\u0035\u004d\u002e\u006f\u005b\u0048\u0064\u004d\u003d\u0063\u003f\u0057\u003d\u0066\u0071\u0031\u0033\u005b\u003b\u002e\u0024\u006a\u0067\u0075\u006f\u0070\u0024\u0055\u007d\u0039\u0055\u0037\u0023\u005f\u0071\u0020\u005e\u007a\u0053\u0027\u0038\u0059\u003b\u0067\u0023\u0033\u0047\u005f\u004e\u0052\u0068\u005e\u0022\u0059\u0054\u0064\u0074\u0077\u0043\u006c\u004d\u0042\u0048\u0025\u0067\u002b\u0026\u0031\u0043\u002a\u006f\u0025\u0032\u004a\u0054\u0026\u002c\u003a\u0078\u0032\u007b\u0077\u003a\u0037\u002b\u003f\u0033\u006d\u0067\u0078\u0020\u0066\u0044\u0041\u003b\u0033\u006f\u0060\u0025\u0033\u002e\u0033\u004c\u0029\u0030\u0068\u0037\u006b\u007e\u004f\u0031\u004d\u0063\u0074\u005f\u0052\u0024\u0030\u0061\u004c\u006d\u0058\u0026\u004e\u0044\u0033\u003e\u0036\u006e\u004f\u0033\u006d\u0041\u003d\u007a\u004d\u005f\u0057\u0056\u0063\u002b\u004b\u0054\u0032\u0037\u0042\u0072\u003c\u003d\u0076\u006d\u0066\u0022\u0047\u003e\u004a\u0046\u0030\u0071\u0058\u005e\u0057\u0061\u0037\u007b\u0020\u0066\u0070\u0068\u0042\u005b\u005a\u007c\u0056\u0074\u0043\u0033\u0053\u0043\u006b\u0032\u005e\u0063\u0074\u0075\u0079\u006c\u004a\u0071\u0064\u004d\u0054\u0030\u0023\u0053\u007e\u007e\u005d\u004f\u0055\u0078\u0028\u0033\u0050\u0049\u0057\u0078\u0049\u0048\u0076\u0022\u0070\u005f\u0031\u0034\u0077\u0036\u003e\u0040\u0031\u003d\u0075\u002e\u005c\u004c\u0045\u0078\u0021\u0053\u004d\u0048\u0069\u005e\u0036\u0066\u0033\u004d\u006e\u0067\u0030\u0052\u0022\u0078\u002d\u0056\u0079\u0052\u0073\u004c\u0040\u005b\u0033\u0064\u0063\u0054\u0039\u003e\u005f\u0074\u0063\u006b\u004f\u0045\u0075\u0051\u0053\u0072\u007c\u0059\u0071\u0051\u0039\u0031\u005b\u0071\u007c\u0064\u007a\u007c\u0059\u0079\u0060\u0077\u0071\u0026\u0047\u0038\u0067\u0073\u0043\u0063\u005e\u0061\u0070\u0022\u0074\u004a\u006c\u0062\u0036\u003d\u0036\u0070\u0039\u004b\u002e\u0020\u0062\u006d\u0064\u0021\u0072\u003d\u002f\u006a\u0021\u005c\u0023\u0061\u0028\u0074\u004a\u0043\u0066\u006f\u0049\u0050\u0029\u0076\u0032\u0069\u0054\u002e\u0031\u0058\u002b\u0067\u0032\u0022\u0055\u0029\u0076\u007b\u0074\u0042\u0057\u0030\u0036\u0045\u006c\u0048\u0077\u0068\u0029\u006e\u0020\u007d\u003b\u0038\u0053\u0054\u004c\u0042\u0079\u0033\u0073\u006d\u004e\u003f\u0065\u0027\u006f\u0034\u0068\u0027\u0033\u0060\u0062\u006a\u004f\u0035\u0068\u0037\u0063\u0020\u0061\u002c\u002f\u005a\u005d\u0028\u002d\u0047\u0055\u002b\u0033\u003c\u007d\u0022\u0039\u0029\u0072\u004d\u0058\u005f\u0037\u005a\u002c\u0049\u0077\u0025\u0054\u002a\u004d\u0055\u007b\u0024\u0071\u003c\u0066\u0061\u0072\u0040\u0073\u003e\u0022\u0075\u007a\u0032\u003d\u0041\u0025\u007d\u0043\u002e\u0073\u0029\u0051\u0058\u0073\u0047\u0035\u0078\u004d\u0074\u0029\u0058\u006e\u007b\u0067\u003d\u0078\u0076\u0035\u0078\u0076\u005f\u0026\u0056\u0062\u0034\u0071\u0055\u0069\u002a\u007e\u005c\u005a\u005b\u006a\u006b\u002e\u002e\u0078\u0050\u0054\u0025\u007d\u005c\u0024\u004f\u0022\u0063\u0053\u0055\u0074\u0024\u0077\u0064\u0068\u004f\u0063\u0064\u0052\u002e\u0060\u0036\u004c\u0057\u0050\u0042\u0057\u006c\u0055\u0073\u006a\u005f\u0074\u0068\u004b\u0033\u006f\u0061\u006a\u0064\u007d\u004c\u0027\u0066\u003c\u002a\u002d\u0045\u0032\u007c\u0070\u006f\u002e\u002c\u0051\u0077\u003c\u003b\u0029\u0032\u0020\u0037\u0037\u002d\u0071\u0077\u004d\u003c\u006e\u005f\u0063\u0067\u002c\u004a\u007c\u007c\u005b\u0060\u006a\u003b\u007b\u0068\u0073\u006f\u006b\u0036\u0061\u0070\u0062\u0074\u0028\u002a\u002f\u0044\u0065\u0062\u003a\u003f\u0032\u007c\u005e\u0047\u0044\u0022\u0027\u005e\u004c\u0070\u0059\u0062\u005f\u0073\u0044\u005b\u007a\u004f\u007c\u0035\u006b\u004a\u0034\u0061\u0039\u004c\u0032\u0033\u0061\u0078\u0073\u0060\u0034\u0073\u0046\u007e\u003c\u007a\u0026\u0074\u003b\u007c\u003e\u004c\u003f\u005e\u0051\u0055\u004b\u0032\u004d\u0057\u0045\u002f\u0067\u002c\u0061\u0036\u0064\u0052\u005d\u002a\u0069\u0031\u0039\u0075\u0063\u006b\u004a\u0078\u0079\u0078\u0021\u0046\u0062\u004e\u0052\u0070\u004d\u0070\u006f\u006f\u0031\u0040\u006f\u0061\u0059\u0036\u0067\u003d\u0022\u003f\u0046\u004d\u0050\u004a\u0043\u005b\u0022\u005c\u002d\u0075\u0039\u0056\u0021\u0033\u0027\u007b\u007b\u0048\u0032\u006c\u0068\u0053\u0039\u004e\u0061\u0053\u0032\u0057\u0054\u004f\u0072\u0023\u006f\u002a\u0048\u0066\u0050\u0075\u0035\u002e\u0021\u0068\u0053\u005a\u0034\u005d\u0039\u007d\u002c\u006e\u004e\u002a\u005a\u003c\u0030\u0045\u007d\u003d\u0065\u0043\u004b\u0053\u005f\u003c\u0023\u003e\u0070\u003d\u0037\u0068\u002c\u0045\u0044\u0032\u005f\u0053\u006e\u0048\u006b\u004c\u0042\u0033\u0045\u006a\u005c\u0047\u0036\u005c\u0039\u0067\u0053\u0071\u005e\u0074\u0068\u0063\u0046\u002c\u005c\u005e\u0044\u007b\u0050\u0038\u005f\u006b\u0059\u0076\u0020\u004a\u0048\u0066\u003b\u0020\u0029\u002f\u0054\u007b\u006b\u006c\u005f\u0067\u006d\u002e\u0044\u0071\u0067\u0076\u005d\u0021\u0048\u0031\u0051\u0078\u0079\u0071\u0051\u0045\u0071\u0076\u006d\u0068\u0052\u007c\u0068\u0024\u0078\u005d\u006d\u0074\u0066\u003f\u0034\u0046\u0062\u0052\u0074\u0023\u0023\u003b\u007d\u003d\u004b\u0034\u0077\u0076\u005b\u0077\u0046\u005d\u0043\u0025\u0066\u0049\u002a\u0042\u0043\u005c\u0051\u0031\u0047\u003c\u0072\u0060\u0029\u0057\u0033\u0038\u0051\u002c\u005c\u0042\u003c\u0033\u0052\u002a\u004f\u0049\u005b\u0027\u0066\u0045\u006a\u0038\u0070\u002f\u0067\u0061\u0056\u0025\u0064\u004c\u007d\u005d\u0043\u002b\u004f\u004f\u002d\u0066\u0053\u0021\u0053\u007e\u006b\u007e\u0062\u0067\u006d\u007c\u004e\u006d\u0036\u0066\u0047\u0077\u002a\u0042\u002c\u0063\u003a\u006f\u004e\u005f\u0057\u0059\u0021\u0065\u0062\u003b\u0037\u0028\u0027\u003a\u0073\u0078\u0030\u0041\u0038\u0055\u0051\u0065\u003d\u0046\u0047\u004b\u007e\u0074\u007b\u0020\u007b\u0047\u0026\u003a\u003a\u0076\u002e\u0071\u0049\u0044\u003b\u0055\u0035\u005a\u005b\u006d\u004d\u003d\u0024\u0056\u006f\u0068\u006c\u0060\u0070\u0025\u006e\u0063\u0041\u0040\u002d\u0034\u0038\u004f\u0074\u007e\u0035\u007d\u0022\u002f\u005c\u0077\u0061\u0053\u0077\u004e\u0070\u007c\u0051\u007d\u007c\u005e\u0053\u0068\u0022\u0070\u0063\u0065\u0059\u004c\u004e\u0052\u0040\u0055\u005c\u0026\u006d\u0028\u0044\u0037\u0076\u0070\u0046\u0064\u0062\u0066\u0061\u007d\u0062\u0062\u004f\u0061\u0066\u0049\u003a\u0062\u0075\u0064\u006d\u0068\u002a\u0047\u0078\u0022\u0049\u003e\u0022\u0053\u003b\u0037\u0071\u002b\u0075\u0038\u0065\u002c\u0051\u0034\u007b\u006a\u0026\u003c\u0023\u002e\u0040\u0027\u004d\u006d\u0039\u0059\u004a\u002b\u0040\u0032\u0070\u0072\u006f\u002e\u0020\u005e\u0031\u0040\u0046\u003d\u003b\u006d\u002c\u007a\u005d\u004e\u005f\u002a\u003e\u0044\u0039\u0065\u0046\u0048\u002a\u002f\u0071\u0027\u0023\u0054\u0045\u0054\u002b\u0024\u005a\u004f\u0076\u002c\u005f\u0023\u0055\u006f\u004e\u0023\u0045\u0038\u0059\u0040\u003e\u0028\u0030\u003b\u002f\u0059\u0055\u0060\u0074\u0023\u007a\u0025\u0025\u002b\u0032\u0055\u002a\u0047\u0075\u0033\u004f\u0023\u0066\u002b\u005b\u0066\u0077\u0051\u0069\u003e\u0056\u005f\u003d\u0068\u006a\u0078\u002b\u0044\u002b\u0041\u006e\u0066\u006a\u0039\u0056\u0049\u0044\u005f\u003e\u003f\u004c\u0022\u006c\u004c\u0057\u003b\u005f\u006f\u005a\u0057\u006f\u0040\u006b\u0031\u003d\u0060\u0068\u0071\u0044\u0021\u0051\u004f\u0040\u004d\u0043\u002e\u0022\u0026\u0072\u0031\u0024\u0064\u0035\u0060\u003f\u0044\u003c\u0053\u003d\u005c\u0021\u007e\u002b\u0038\u0034\u004b\u004c\u0028\u0050\u0069\u005b\u004c\u003a\u005c\u0074\u006d\u0044\u0052\u0068\u007d\u0052\u0024\u0021\u006b\u0054\u005e\u0037\u006c\u003a\u003b\u005b\u0042\u0064\u005b\u0049\u0050\u004b\u0065\u0059\u004f\u0054\u005d\u0025\u0062\u004c\u0040\u0055\u0067\u002d\u002d\u0077\u0043\u0037\u0025\u0079\u006e\u0040\u0069\u0066\u0064\u0043\u006a\u006a\u003c\u0074\u0069\u007d\u0056\u0068\u002d\u002a\u0038\u0061\u004e\u0021\u004b\u002b\u004d\u003c\u0045\u0020\u0023\u003a\u0033\u0044\u0072\u0060\u0053\u0069\u0037\u0061\u006a\u0047\u004a\u003e\u0071\u0063\u0072\u0054\u002e\u0054\u005c\u0074\u006f\u005c\u0039\u0028\u003d\u002b\u0022\u0037\u004e\u0065\u0057\u007b\u007c\u0023\u002d\u0048\u005e\u002f\u003c\u003b\u002c\u005a\u0056\u0067\u0047\u003c\u0073\u0060\u002e\u0037\u0030\u0051\u0022\u0033\u0049\u005b\u0024\u0075\u0062\u0048\u0043\u0072\u0037\u007a\u0055\u0072\u0043\u0026\u006d\u0021\u0062\u0050\u006a\u0020\u0050\u0071\u0060\u0043\u006b\u005e\u002c\u0074\u0059\u0034\u0036\u003e\u007b\u0061\u004d\u005a\u005c\u0021\u0067\u007a\u0021\u004f\u0052\u003f\u005e\u0066\u0020\u0067\u002a\u003a\u0032\u0077\u0031\u0035\u005a\u002c\u007e\u004c\u0025\u0060\u005e\u0034\u004a\u006f\u003b\u0021\u0065\u0021\u0055\u0055\u0024\u0032\u007c\u005c\u0027\u0046\u0046\u0033\u0027\u0056\u004a\u0073\u005d\u005e\u0067\u0061\u0029\u0050\u004b\u0070\u0024\u0047\u0049\u003b\u007c\u005d\u0049\u0071\u0028\u0036\u0036\u003b\u007d\u0041\u0061\u007b\u0069\u0042\u0058\u005c\u004e\u0037\u006a\u006c\u002b\u0077\u007d\u0058\u0058\u002d\u0020\u005b\u0043\u0073\u0020\u0022\u0024\u0079\u0027\u0037\u0061\u0076\u0071\u0051\u0051\u005a\u0033\u006f\u006e\u004e\u002b\u0032\u0063\u0033\u006c\u0033\u0066\u003d\u0023\u0078\u002a\u002f\u0022\u0040\u002d\u0046\u0042\u0043\u0070\u0032\u006d\u0035\u002f\u007b\u007b\u0040\u0046\u0056\u004d\u0079\u007a\u005c\u0073\u0064\u005a\u003b\u007d\u0033\u0021\u004a\u004e\u005c\u002b\u0030\u0044\u0038\u0060\u0048\u0055\u007b\u0025\u0074\u0052\u0077\u0040\u0056\u007e\u003b\u007b\u0023\u0063\u002b\u0060\u004c\u0067\u0079\u007e\u006b\u0041\u006f\u0056\u0048\u002a\u0059\u0079\u007a\u0033\u0074\u0069\u0052\u003e\u0035\u006f\u0045\u0028\u0077\u0045\u003d\u0035\u0069\u0078\u0075\u0048\u003d\u003d\u0077\u005a\u0074\u002a\u0076\u0055\u0043\u0050\u0048\u0050\u002e\u0046\u0031\u0025\u0076\u0071\u0024\u0076\u0050\u006b\u0050\u002a\u0060\u0030\u005b\u005b\u0047\u0031\u0032\u0071\u0064\u007b\u0053\u0050\u0066\u0030\u0046\u006f\u003e\u004c\u002b\u004a\u005d\u0027\u0030\u0037\u003a\u0027\u003a\u0024\u004b\u002e\u006f\u007a\u0029\u002e\u0073\u006c\u0047\u0025\u0056\u004d\u0036\u0036\u005f\u0033\u0045\u0033\u0042\u002f\u003d\u0067\u004d\u005a\u0062\u0039\u0020\u0022\u0042\u003e\u0050\u002a\u0071\u003d\u0046\u0060\u004d\u0074\u0051\u0031\u002e\u003b\u0067\u006c\u003a\u006a\u007e\u0073\u002f\u0049\u0035\u004d\u0072\u005f\u0037\u0029\u0039\u004a\u0032\u0073\u006c\u0020\u004d\u0041\u0067\u0064\u0046\u0022\u0058\u0022\u0063\u0027\u0049\u003e\u007d\u002a\u0071\u007d\u0024\u006b\u0032\u006d\u002f\u0066\u0046\u007c\u0035\u006c\u007e\u006e\u007c\u005e\u0072\u0061\u004a\u0048\u0064\u0048\u0053\u005b\u0032\u0035\u005d\u0035\u0064\u0076\u003e\u0033\u002d\u0068\u002a\u0048\u0071\u005b\u0037\u0069\u0068\u0022\u007e\u0066\u007e\u0070\u0058\u007b\u0062\u0039\u0077\u0032\u0028\u0076\u0074\u0037\u0029\u0049\u0032\u0050\u0043\u0062\u0052\u004c\u0073\u0050\u0037\u0072\u0079\u0030\u0058\u002f\u002a\u002a\u006c\u0030\u0055\u002a\u004d\u0064\u0037\u0026\u005b\u0047\u0053\u002a\u0025\u002a\u0066\u0059\u0025\u0068\u0023\u0046\u005e\u007b\u0039\u0032\u005e\u0079\u004b\u0032\u005a\u0022\u002a\u0041\u0035\u002e\u0068\u0066\u003c\u0057\u0067\u0070\u003e\u007b\u0028\u004c\u002a\u0065\u0047\u0053\u003e\u004d\u0050\u007a\u0075\u0041\u002e\u0069\u006b\u0057\u0072\u0078\u0045\u005d\u0061\u007d\u0061\u0032\u005c\u0038\u006c\u0045\u0051\u0075\u0054\u003d\u003e\u0046\u004c\u0031\u0024\u0079\u0031\u0042\u002f\u0079\u004a\u0024\u0020\u0053\u006c\u003f\u0048\u006f\u003d\u0021\u0048\u002e\u006f\u007c\u0037\u0049\u0069\u002b\u005e\u0032\u0054\u0043\u0030\u0038\u0048\u004c\u0029\u0063\u0021\u003d\u0079\u004e\u0076\u0041\u005d\u006a\u0058\u006c\u002d\u0042\u0071\u0079\u0025\u0031\u0045\u007e\u002d\u007d\u0055\u006f\u0036\u0067\u0065\u007d\u0030\u0049\u005a\u0061\u0045\u0063\u0050\u0031\u0075\u0040\u007b\u003f\u0031\u0025\u007a\u0028\u0077\u005b\u0062\u0049\u0070\u003c\u0073\u0070\u0065\u0068\u0043\u004a\u002d\u006e\u0040\u0078\u0079\u0028\u0061\u0073\u0067\u006b\u0029\u0076\u003a\u006a\u0057\u002c\u002a\u0040\u002a\u0027\u0072\u0023\u0063\u0031\u0047\u004d\u0020\u0029\u0020\u0074\u0022\u005a\u005e\u0047\u003f\u0064\u003e\u0069\u003a\u005b\u002e\u002c\u0053\u0039\u0034\u0056\u0036\u004e\u0055\u0070\u0076\u0061\u0046\u0045\u0032\u005d\u004b\u0061\u0036\u0058\u0046\u0047\u0059\u0060\u0069\u0075\u0067\u005a\u0036\u0032\u007b\u0038\u0040\u002f\u0050\u006c\u0040\u005f\u005c\u006a\u006c\u0037\u0067\u003e\u0074\u002b\u0049\u006a\u004f\u0046\u005e\u004d\u007d\u006d\u0052\u006c\u0050\u0058\u0052\u006b\u005e\u0044\u006e\u004e\u002c\u004a\u0053\u0028\u003e\u0065\u0042\u002a\u0073\u0067\u0044\u0024\u003d\u0069\u007b\u0058\u0068\u0034\u003a\u0040\u006a\u002f\u0058\u004f\u0071\u0042\u005b\u006e\u0042\u003d\u0070\u0021\u006b\u004d\u0065\u002a\u0061\u0050\u0065\u0041\u0042\u002a\u0060\u0059\u0073\u0073\u006a\u0021\u0071\u0075\u0048\u0048\u0047\u0062\u002e\u0037\u0055\u0051\u0021\u0029\u002a\u0065\u0056\u0049\u003e\u0055\u002a\u0022\u0033\u0026\u0024\u003c\u0043\u003f\u005d\u0078\u007b\u005f\u004a\u0077\u006b\u0043\u0070\u003e\u0024\u0035\u002b\u0064\u0049\u005f\u002a\u0061\u0030\u0031\u0034\u0036\u0031\u0074\u006d\u0070\u0026\u0074\u0041\u0072\u0059\u0033\u005e\u0066\u007e\u0021\u0039\u004f\u004b\u0046\u007c\u003f\u0020\u0072\u005b\u0059\u004d\u0068\u0049\u006d\u0023\u0066\u0043\u002e\u0076\u0050\u006b\u0023\u002a\u0040\u0024\u006b\u0034\u006c\u004c\u0052\u005e\u0045\u0078\u006f\u0026\u0053\u0021\u005d\u0078\u0033\u003d\u005c\u006d\u0071\u002c\u006a\u007d\u006a\u0045\u0070\u0079\u004f\u0059\u0067\u0024\u005c\u005f\u0068\u002f\u007d\u006a\u0029\u0044\u0072\u005a\u004b\u0031\u0041\u0025\u0038\u0074\u003b\u003e\u007d\u0025\u0064\u0052\u0035\u0044\u0063\u0058\u004c\u0060\u0025\u0035\u0078\u0071\u0035\u006a\u002a\u0043\u0033\u006e\u0036\u004d\u0035\u0051\u0029\u0043\u0027\u005e\u003f\u0056\u0051\u002a\u002c\u0052\u0079\u0029\u0046\u0043\u0024\u0030\u0036\u0055\u0072\u0047\u0031\u007e\u007a\u0045\u0044\u0032\u006a\u003d\u006f\u0044\u004a\u006f\u0036\u0067\u004f\u0023\u0056\u006c\u0043\u0027\u005e\u006d\u0069\u002a\u005d\u0057\u0031\u003f\u0067\u0033\u002e\u0025\u006e\u0040\u0022\u006a\u0023\u002b\u004b\u0070\u005e\u0046\u004d\u006c\u0026\u005a\u006f\u003b\u0056\u002e\u007d\u0074\u0069\u0074\u0024\u002e\u0040\u0065\u004f\u0022\u0067\u0032\u0043\u0042\u0064\u007d\u0030\u0063\u0049\u003b\u0068\u0027\u007c\u0021\u007a\u0042\u003b\u0028\u007c\u0031\u003e\u005c\u0039\u003b\u006d\u0049\u0058\u006c\u006c\u0064\u0053\u0051\u0067\u0022\u0063\u002f\u004d\u0025\u007d\u002e\u002b\u0045\u0060\u0039\u006e\u0062\u0054\u0038\u0075\u0079\u0061\u0041\u0038\u0072\u006c\u003b\u004a\u003e\u0056\u005a\u0068\u006f\u0067\u005b\u0031\u0040\u0037\u0031\u006b\u005e\u0052\u0031\u0041\u005c\u0064\u0062\u0055\u006c\u002f\u005a\u0058\u007e\u0021\u0040\u005c\u0040\u004d\u0044\u003a\u004f\u0064\u0056\u0048\u0068\u007e\u003a\u006d\u007b\u004b\u006b\u003c\u0041\u0025\u006a\u0037\u0025\u0038\u005a\u006e\u0045\u0030\u0028\u004a\u007a\u0026\u0030\u004e\u007e\u002c\u0048\u0056\u0078\u0079\u0059\u0026\u006c\u0033\u004e\u0069\u004d\u0060\u0074\u0030\u0028\u0022\u004c\u006b\u0040\u006a\u0056\u0031\u0068\u0047\u0070\u0025\u004a\u002b\u006b\u006e\u0021\u0020\u0078\u0040\u0077\u0064\u0044\u0067\u0028\u0039\u0028\u004b\u005c\u002b\u0042\u0025\u0067\u0060\u0022\u0054\u003e\u003a\u0035\u0050\u003f\u004c\u0060\u0059\u005c\u0062\u0069\u0063\u0053\u0021\u005f\u0067\u0059\u0072\u0047\u004d\u0059\u0045\u006a\u003d\u0035\u0067\u0030\u0073\u0038\u0054\u0072\u0034\u0036\u0052\u0021\u0074\u0024\u0049\u0051\u0030\u0047\u006a\u002f\u0065\u0025\u0076\u0051\u0072\u0029\u007e\u0050\u0047\u0032\u0052\u005c\u0051\u0029\u0055\u003c\u003e\u0065\u0045\u006f\u0068\u007a\u0067\u0075\u006c\u0069\u0022\u0023\u0043\u0042\u003f\u0035\u005f\u0079\u007a\u0037\u0064\u0023\u002f\u005c\u0062\u0071\u005f\u007d\u0052\u004f\u0071\u0054\u0028\u0058\u0063\u0073\u0049\u0060\u005b\u0040\u0065\u0023\u0070\u005e\u0049\u004f\u0036\u0026\u0035\u0079\u0063\u005f\u0062\u0079\u004c\u0044\u0021\u0023\u0020\u0031\u003e\u0066\u0042\u0048\u003a\u0021\u002c\u0025\u004d\u004e\u0078\u0020\u007b\u006f\u0072\u0062\u0027\u007b\u002a\u007d\u0033\u003c\u0054\u0049\u0048\u0035\u0041\u006b\u0042\u0076\u0060\u0068\u002a\u004c\u0048\u0029\u0028\u005a\u0041\u005a\u004d\u0049\u003b\u0050\u007d\u0076\u006e\u0048\u0040\u0030\u005c\u002e\u0054\u006f\u0032\u0026\u0046\u003b\u0066\u003d\u0043\u0025\u004a\u0021\u0046\u006f\u006d\u005a\u002e\u0038\u0062\u0066\u0024\u0075\u0062\u0064\u005c\u0050\u0045\u0030\u0024\u0063\u0032\u004c\u0067\u005e\u0062\u0064\u0033\u0068\u0072\u0068\u0047\u0034\u005d\u0069\u0059\u0056\u0074\u005d\u002e\u003c\u0057\u005f\u007e\u0059\u0064\u0027\u004e\u004c\u005b\u003b\u0023\u0077\u0067\u0047\u0046\u006a\u0065\u0068\u007c\u0077\u005d\u0068\u0057\u003e\u002e\u005a\u0032\u0038\u0025\u0021\u0049\u006f\u003b\u0044\u006a\u006a\u007e\u002a\u0063\u0037\u005e\u0059\u0023\u005c\u0034\u006f\u0074\u005b\u0039\u0036\u003e\u0045\u0075\u0029\u002c\u0044\u0020\u0029\u006e\u002d\u006c\u0061\u005f\u005a\u0071\u0021\u0060\u005f\u0051\u0045\u0076\u0075\u002e\u0062\u004a\u002a\u0055\u0029\u002a\u0072\u006d\u003d\u0054\u0021\u002a\u003d\u007d\u005e\u003d\u0058\u0049\u0024\u0073\u0039\u0053\u0068\u0047\u0041\u0075\u0020\u0064\u005f\u0020\u0046\u0053\u0021\u0070\u0027\u0050\u006d\u004d\u0062\u0065\u0030\u006c\u005e\u004c\u0033\u0026\u0042\u004a\u0060\u0046\u005f\u003f\u004c\u0070\u0025\u0060\u0062\u002a\u0049\u007b\u0076\u002f\u0054\u0078\u005e\u0072\u0051\u0058\u0031\u0044\u002c\u0058\u0022\u0055\u0056\u006e\u006b\u002a\u0075\u003d\u003f\u007b\u002e\u004d\u004b\u0041\u004d\u005e\u0042\u0056\u0074\u0065\u0070\u0058\u0028\u007c\u0036\u004d\u004b\u002f\u0049\u0055\u0050\u0040\u0054\u0072\u0042\u0075\u005c\u0044\u0043\u0079\u0037\u0042\u0049\u004c\u0065\u004d\u0061\u0061\u0062\u0045\u0048\u0078\u002b\u0038\u0054\u0077\u0050\u0047\u003c\u0036\u006d\u0041\u0078\u0029\u0067\u005f\u0041\u0063\u002a\u004a\u0050\u007e\u004c\u002d\u0030\u0041\u007a\u0024\u0074\u003d\u0035\u007c\u0049\u0028\u006a\u007a\u0045\u0052\u0067\u007d\u0057\u006a\u0047\u0038\u0060\u004a\u002d\u0034\u0026\u0020\u0079\u004e\u0070\u0052\u0065\u0049\u0052\u005e\u002c\u006f\u006a\u0053\u0078\u003e\u0020\u0077\u0038\u0040\u0042\u0068\u0052\u0027\u0054\u0077\u0040\u005a\u006d\u004f\u0041\u005d\u0045\u0023\u005c\u0055\u004f\u0022\u0032\u0071\u007e\u0028\u0036\u0059\u0078\u0068\u004d\u002d\u006c\u003d\u0033\u002a\u006d\u0062\u0048\u0021\u0039\u0061\u0045\u0028\u0066\u0060\u004b\u0060\u003f\u003b\u003e\u007d\u006d\u0030\u007e\u0034\u0077\u0043\u0074\u0066\u0071\u007d\u0058\u003f\u0025\u0057\u005f\u002e\u006e\u0037\u0057\u002c\u0055\u0076\u0053\u007c\u002e\u0055\u002d\u0051\u0059\u004d\u0044\u003d\u002e\u0044\u004b\u0035\u0039\u0058\u0026\u0072\u0020\u0065\u0026\u003b\u0077\u004e\u0033\u0039\u0039\u006b\u0077\u005c\u003d\u006b\u0022\u004d\u0029\u0051\u0070\u0032\u006e\u0064\u0037\u0041\u006b\u0076\u0076\u007c\u004a\u0034\u007b\u0062\u003d\u006f\u0041\u0078\u0047\u0023\u003f\u0035\u0054\u005a\u0067\u0072\u006e\u0031\u0051\u0048\u007d\u007b\u005e\u003a\u0026\u0069\u006b\u0042\u0043\u007d\u007e\u0063\u0070\u004e\u003e\u007c\u0027\u002a\u0079\u0064\u0073\u0029\u005d\u006c\u0032\u002a\u0034\u007e\u002b\u0040\u0046\u005e\u006e\u0056\u005a\u0069\u0040\u007d\u0072\u0047\u0041\u0029\u005a\u0079\u007a\u003b\u005a\u003f\u0034\u0054\u0065\u0078\u0034\u005b\u0046\u007a\u004f\u004e\u005f\u0076\u004a\u005a\u007a\u0057\u007c\u0057\u005d\u0030\u0067\u0036\u0034\u0044\u0047\u003f\u0061\u006e\u007e\u0040\u0050\u0064\u003a\u002e\u0066\u0033\u0041\u004c\u0074\u0072\u0046\u003e\u0049\u003b\u0055\u0066\u0062\u005d\u0060\u004a\u0067\u0031\u004e\u0072\u0044\u0035\u004c\u005a\u0057\u0077\u005c\u006e\u004d\u0057\u0062\u005b\u0021\u007d\u005f\u002f\u002f\u0022\u002d\u0044\u0032\u0062\u0040\u0078\u002c\u0076\u003d\u0054\u0077\u0043\u007d\u0078\u007d\u0036\u0068\u004d\u007d\u0077\u0022\u005b\u002a\u005c\u0079\u004f\u0038\u0060\u0033\u0076\u005d\u0042\u0075\u0078\u006e\u0047\u004b\u0056\u0069\u003b\u0049\u006e\u004a\u002f\u004e\u005e\u0031\u002a\u0045\u0066\u0024\u005e\u0059\u002d\u007e\u0073\u0060\u0040\u0052\u0032\u0055\u0068\u005b\u002c\u0027\u0054\u0052\u0053\u0053\u005b\u0022\u0054\u0072\u006d\u0062\u0079\u003e\u007a\u0021\u0021\u0068\u007d\u003f\u0076\u002d\u004c\u0055\u0029\u0079\u0068\u0072\u0031\u005c\u0024\u0050\u0061\u0027\u0060\u005b\u0020\u0073\u0048\u007e\u005b\u0042\u004a\u0059\u003c\u0039\u0042\u003e\u0054\u0070\u0063\u0053\u004e\u005c\u0058\u0066\u0038\u0069\u003d\u0072\u005b\u007a\u0056\u0032\u0060\u0051\u0077\u0040\u004e\u0039\u005c\u006c\u007c\u007c\u0064\u0054\u0038\u0069\u007c\u0032\u0067\u003e\u0038\u0020\u005b\u0058\u002f\u0045\u0032\u003b\u0078\u005c\u0074\u0073\u005a\u0025\u005a\u0030\u002c\u006f\u0050\u0077\u005b\u0020\u005b\u0037\u0038\u006e\u0020\u002c\u004c\u0078\u0074\u004a\u0037\u007b\u0058\u007c\u0029\u004f\u007c\u0023\u0025\u0041\u0050\u0047\u0032\u0038\u0022\u002f\u0048\u0041\u0060\u0037\u0064\u005e\u002a\u002a\u003e\u002e\u0046\u0064\u0073\u005c\u004d\u0067\u0021\u0077\u0072\u006e\u0063\u002c\u003c\u0045\u004a\u0060\u003f\u0068\u0049\u0063\u005b\u0056\u003a\u003b\u003c\u003b\u0062\u0047\u004d\u0063\u0070\u0055\u007c\u0045\u003e\u0073\u0062\u0025\u0052\u0020\u007d\u003d\u006f\u005a\u0060\u003f\u0079\u0041\u0020\u005b\u004c\u005d\u0042\u0056\u006b\u003d\u0022\u0065\u002f\u0023\u002d\u0050\u0071\u0045\u007a\u0023\u0046\u003b\u0056\u0042\u0041\u0039\u005a\u0077\u0079\u003f\u0051\u002e\u002d\u0036\u0045\u0049\u0047\u0032\u0028\u0059\u006c\u005e\u003c\u0037\u004c\u0060\u0038\u004e\u007c\u005d\u002a\u002a\u0036\u0065\u004e\u0024\u0024\u004c\u0059\u0053\u005d\u0021\u0048\u0064\u0052\u0044\u0054\u0024\u0064\u0040\u007c\u007d\u0060\u0029\u0065\u0077\u0033\u0031\u0076\u0041\u003e\u004c\u0047\u0070\u002c\u006f\u004e\u006a\u0027\u003c\u0052\u0076\u0051\u0061\u0037\u0024\u003a\u0066\u004b\u0062\u007b\u0074\u0054\u004d\u0067\u0054\u0022\u004f\u0057\u0049\u0036\u003c\u0043\u003e\u0062\u0053\u0062\u0054\u006d\u0075\u0055\u005f\u003f\u006d\u0030\u0043\u0020\u0067\u0056\u004a\u002f\u0043\u0038\u0068\u007a\u007e\u006b\u0033\u004e\u0068\u0069\u0036\u005b\u005d\u0043\u0023\u0062\u0039\u007a\u0034\u0074\u0056\u0066\u007a\u0036\u004f\u0048\u0048\u0032\u0062\u003c\u0070\u007a\u005b\u0065\u0066\u006e\u003e\u0023\u0024\u0044\u0046\u0042\u002d\u005c\u007e\u0074\u006b\u007b\u0051\u005b\u002d\u0037\u003d\u0072\u002e\u0028\u0022\u0078\u0077\u007c\u0057\u006e\u0066\u0029\u007b\u0044\u0048\u0049\u0051\u002a\u006a\u0069\u006f\u0043\u002b\u0064\u0077\u0049\u003f\u003f\u0030\u005d\u004b\u0070\u0053\u0022\u0036\u004a\u0079\u0072\u004a\u007c\u0050\u0041\u005e\u006e\u004e\u0029\u0074\u0077\u0053\u0060\u002f\u0029\u0072\u006e\u003d\u003c\u003e\u0028\u0055\u007e\u0072\u0032\u0059\u0052\u0024\u007c\u0053\u0042\u0059\u0036\u0064\u0027\u0066\u006f\u0074\u0042\u0067\u0022\u005b\u0050\u006b\u0065\u007e\u0021\u004a\u004c\u002b\u0077\u007b\u003c\u0063\u003f\u006f\u0073\u0035\u002b\u0057\u0041\u0054\u004e\u0020\u0041\u0025\u0044\u0076\u003e\u005d\u0043\u006a\u0022\u0059\u0030\u0042\u0078\u003f\u0065\u003d\u0036\u0070\u005b\u0037\u0055\u0027\u0047\u0041\u0021\u0039\u006e\u0059\u0041\u003f\u0074\u006a\u0065\u002a\u0023\u004c\u0035\u005d\u0051\u004a\u004a\u0044\u002f\u0024\u006c\u0033\u0056\u005f\u003d\u002b\u004c\u006f\u0046\u006c\u0067\u005f\u0048\u0064\u0024\u003d\u0047\u0046\u0063\u0027\u0079\u003a\u007c\u0025\u006a\u0039\u003b\u0022\u0040\u0073\u0050\u002e\u004d\u0065\u0071\u0067\u0020\u0028\u005b\u0021\u006a\u004b\u0046\u002a\u0024\u0048\u0063\u0077\u0022\u0021\u0072\u0058\u003a\u0044\u006e\u0025\u0072\u0058\u003f\u0021\u006b\u0072\u0035\u006e\u004d\u0028\u004c\u0064\u0020\u0044\u004e\u0076\u0036\u0035\u005e\u0024\u0076\u0066\u004d\u0076\u0071\u0075\u003c\u0046\u002f\u007e\u0076\u003d\u0028\u006d\u0073\u0064\u0071\u0074\u002e\u0034\u006c\u0049\u0070\u0075\u0038\u0038\u0029\u0063\u004a\u003a\u005b\u005c\u0074\u0055\u002c\u0074\u006d\u0065\u0041\u0035\u003f\u003a\u0027\u004c\u006f\u0023\u0076\u0027\u0040\u005d\u004a\u003e\u0038\u0078\u005e\u003b\u0021\u005d\u0050\u006f\u0078\u0034\u006b\u0071\u004e\u0043\u005a\u0065\u0037\u0068\u0073\u0037\u007d\u0054\u005e\u007a\u0052\u0045\u004e\u007c\u005b\u0079\u0022\u004e\u0032\u0054\u0073\u003f\u0061\u0051\u0033\u0065\u0029\u0033\u0025\u0068\u0058\u0069\u0055\u0062\u004c\u004a\u0031\u005f\u006f\u002d\u0025\u007e\u0027\u0079\u003a\u0039\u004d\u0045\u0040\u0058\u006d\u0040\u0023\u0065\u007c\u0070\u0034\u004e\u0062\u003c\u006c\u0026\u0048\u0052\u0034\u0048\u0063\u0046\u0066\u006a\u006e\u005c\u0031\u0031\u005d\u0036\u0021\u003e\u0024\u0041\u0043\u006f\u0073\u0065\u002a\u0040\u002a\u0031\u007c\u005a\u0067\u002a\u0063\u006f\u007e\u0037\u006a\u007e\u0058\u0057\u007b\u0077\u005e\u0046\u002f\u0074\u0048\u0042\u0033\u0026\u0037\u003c\u0035\u006c\u003b\u0072\u0022\u0078\u0078\u0060\u003e\u007a\u003c\u0079\u007a\u003a\u007a\u0053\u007b\u004d\u006d\u003e\u003e\u0021\u0030\u005c\u0023\u0055\u005c\u004a\u0072\u0053\u0029\u0032\u0068\u0034\u0055\u0078\u0024\u0038\u002a\u002d\u004b\u006b\u002b\u004a\u0025\u002a\u0049\u0034\u006c\u0060\u0057\u0023\u0072\u002f\u004e\u005f\u0053\u0052\u0035\u005c\u0057\u004f\u005b\u0030\u0074\u0029\u007d\u006c\u0053\u0076\u0046\u0027\u003c\u0072\u0047\u0067\u007c\u0029\u006c\u0021\u0075\u005b\u0028\u0063\u0021\u005f\u005b\u0037\u0020\u0026\u006b\u005c\u0037\u0068\u0058\u0078\u003b\u0027\u0073\u0053\u0040\u0046\u0068\u0051\u006a\u0058\u0049\u007d\u0061\u0046\u005f\u0026\u005d\u007b\u006a\u003f\u0074\u0052\u0024\u002b\u0050\u0064\u007c\u0046\u0072\u003e\u0052\u0035\u0065\u0072\u0073\u006a\u004a\u004f\u0074\u0064\u0036\u0069\u0029\u0037\u0079\u005a\u0030\u0060\u005c\u002d\u005d\u005d\u0059\u002b\u0030\u0020\u007a\u006b\u0027